<template>
  <div class="orderpaybox">
    <NProgress v-if="loadingflag" />
    <!--    选择取餐方式-->
    <div class="takeFood">
      <div v-if="shopcarlist.length > 0">
        <div class="storename">
          <div v-if="!flagA">
            {{ shopcarlist[0].name || shopcarlist[0].storeName }}
          </div>
          <div v-else>{{ locationdetail }}</div>
        </div>
        <div class="storeaddress">
          <div v-if="!flagA">
            {{ shopcarlist[0].address || shopcarlist[0].storeAddress }}
          </div>
          <div v-else>{{ location }}</div>
        </div>
      </div>
      <div class="pickupMethodBox">
        <div
          v-for="(item, index) in flagA ? pickupMethod.slice(2, 3) : num1 == 3 ? pickupMethod.slice(3) : pickupMethod.slice(0, 2)"
          :key="index" class="pickupMethod" :class="{ pickupMethod2: packFlag == item.packFlag }"
          @click="changePackFlag(item)">
          <div class="circle" v-if="packFlag == item.packFlag">
            <van-icon name="checked" color="#FFBC0C" size="20px" />
          </div>
          <div class="imgBox">
            <img class="img" :src="num2 == 1 ? item.icon : item.icon2" alt="">
          </div>
          <div class="titleBox">
            <div class="title" :class="{ title2: packFlag == item.packFlag }">{{ item.title }}</div>
            <div class="text" :class="{ text2: packFlag == item.packFlag }">{{ item.text }}</div>
          </div>
        </div>
      </div>
    </div>
    <!--    联系方式-->
    <div class="box takeFood phoneBox">
      <div>
        <div class="connection">联系方式</div>
        <div class="receive">用于接收取餐号</div>
      </div>
      <div class="phone">{{ phone }}</div>
    </div>
    <!--    餐品详情-->
    <div class="box takeFood">
      <div class="goodDetail">餐品详情</div>
      <div class="goodList">
        <div v-for="item in goods" :key="item.code" class="goodItem">
          <div class="goodImg">
            <img class="img"
              :src="item.displayImage || item.detail?.image || item.detail?.img || item.itemImage || item.goodImg || item.imageUrl || item.detail.product_img || item.detail.detailImgUrl"
              alt="">
          </div>
          <div class="rightBox">
            <div>{{ item.displayName || item.itemName || item.goodName || item.nameCn || item.detail.product_name ||
              item.detail.title }}
            </div>
            <div class="items">
              <div v-if="item.items">
                <div v-for="(item2, index2) in item.items" :key="index2" class="item2Name">
                  {{ item2.count }} x {{ item2.name }}
                </div>
              </div>
              <div v-else>{{ item.goodlistname || item.listname || item.specifications }}</div>
            </div>
            <div class="quantityBox">
              <!--              {{ item.quantity }}-->
              <div class="quantity"></div>
              <div class="priceBox">
                <span>￥</span>
                {{ num1 == 2 && !flag ? (item.priceHead || item.fullPrice || item.price) : (item.sumprice || item.price
                  || item.fullPrice || item.detail?.salePrice) }}
                <!-- {{ num1 == 2 && !flag ? item.priceHead : (item.sumprice || item.price || item.fullPrice ||
                  item.detail.salePrice) }}  -->

                <span class="quantity">x {{ item.count || item.quantity }}</span>
              </div>
            </div>
          </div>
        </div>
        <div class="unfoldBox" @click="unfold" v-if="shopcarlist.length > 2">
          <div>{{ !isUnfold ? '展开' : '收起' }}(共{{ shopcarlist.length }}项)</div>
          <div class="unfold" :class="{ unfold2: isUnfold }">
            <img class="img" src="../../assets/backimage/zk.png" alt="">
          </div>
        </div>
      </div>
    </div>
    <!--    配送费-->
    <div class="box takeFood phoneBox" v-if="flagA">
      <div>
        <div class="connection">预估配送费</div>
        <div class="receive">近期运力紧张，配送时效无法保证~</div>
      </div>
      <div class="phone deliveryPrice"><span>￥</span>{{ deliveryPrice }}</div>
    </div>
    <!-- 支付方式 -->
    <!--    <div class="box">-->
    <!--      &lt;!&ndash; &ndash;&gt;-->
    <!--      <Payment :result1="result" :cardList="cardList" @getResult="getResult"></Payment>-->
    <!--    </div>-->
    <!-- 购买须知 -->
    <div class="box takeFood">
      <div class="instructions">
        <div class="s1">购买须知</div>
        <div>
          <van-checkbox class="s2" v-model="checked1" checked-color="#ee0a24">已阅读并同意</van-checkbox>
        </div>
      </div>
      <div class="inner" v-html="goumaixuzhi" style="font-size: 14px;"></div>
    </div>
    <!--    支付密码-->
    <PayPassword :isShow="isShow" @input="input" @onInput="onInput"></PayPassword>
    <!--    底部按钮-->
    <div class="footer">
      <div class="footerBtn" :class="{ footerBtn2: num2 == 1, footerBtn3: num2 == 2, footerBtn6: num1 == 6 }">
        <div class="cartIconBox">
          <div class="cartIcon">
            <img class="img" src="../../assets/backimage/Vector-1.png" alt="">
          </div>
          <div>
            <div class="cartPrice">
              ￥<span class="priceText">{{ sumprice.toFixed(2) }}</span>
            </div>
          </div>
        </div>
        <div class="order" @click.stop="toPay">
          <div>去支付</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>

import Payment from '@/components/Payment.vue';
import PayPassword from "@/components/PayPassword.vue";
import { getcardList, getcardPay, flkpay, wxpay, pay_success } from "@/api/pay.js"
import { getsingle, getPhone, getOderList, create_order } from '@/api/service'
// getorderdetail
import { List } from 'vant';

export default {
  components: { Payment, PayPassword },
  data() {
    return {
      num1: 0,
      num2: 0,
      // 取餐方式
      pickupMethod: [
        {
          packFlag: '0',
          title: "堂食",
          text: "店内用餐",
          icon: require("../../assets/backimage/t1.png"),
          icon2: require("../../assets/backimage/t2.png"),
        },
        {
          packFlag: '1',
          title: "外带",
          text: "打包带走",
          icon: require("../../assets/backimage/w1.png"),
          icon2: require("../../assets/backimage/w2.png"),
        },
        {
          packFlag: '2',
          title: "立即配送",
          text: "",
          icon: require("../../assets/backimage/bick.png")
        },
        {
          packFlag: '1',
          title: "自取",
          text: "",
          icon: require("../../assets/backimage/t1.png"),
          icon2: require("../../assets/backimage/t2.png"),
        },
      ],
      storecode: "",
      goods: "",
      phone: "",
      type: "",
      openid: "",
      flagA: false,
      checked1: "true",   //购买须知是否勾选
      checked: "",
      flag: true,
      fooddetail: [],
      countbox: [],
      moneybox: [],
      shopcarlist: [],   //购物车内的商品
      packFlag: "0",
      orderType: "1",
      result: [],
      cardList: "",
      // 外卖
      location: "",
      locationdetail: "",
      goumaixuzhi: "",
      flagB: true,
      sumprice: 0,
      receiverLng: "",
      receiverLat: "",
      address_id: "",
      // 配送费
      deliveryPrice: "",
      // 支付变量
      dkprice: "",
      wxprice: "",
      ka_ids: "",
      // 密码框
      isShow: false,
      pass: "",
      loadingflag: true,
      verify: [],
      isUnfold: false,
      address_Item: {}
    };
  },
  created() {
    if (localStorage.getItem("openid")) {
      this.openid = localStorage.getItem("openid")
    }
    this.flagA = this.$route.query.flag
    if (this.flagA) {
      if (sessionStorage.getItem('address_Item')) {
        this.address_Item = JSON.parse(sessionStorage.getItem('address_Item'))
        this.location = this.address_Item.addr + this.address_Item.number
        this.locationdetail = this.address_Item.contact
        this.address_id = this.address_Item.id
      }
      this.packFlag = 2
    }

    // 🔧 不要从 verify 获取，直接从 goods 获取
    // this.verify = JSON.parse(sessionStorage.getItem("verify"))
    // if (this.verify) {
    //   this.goods = this.verify.slice(0, 2)
    // }

    this.num1 = this.$route.query.num1
    this.num2 = this.$route.query.num2
    this.type = this.$route.query.type
    this.deliveryPrice = Number(this.$route.query.deliveryPrice).toFixed(2)
    if (this.num1 == 3 && !this.flagA) {
      this.packFlag = 1
    }

    this.getsinglelist()
    this.getcard()

    // 统一从 goods 获取数据
    const goodsData = JSON.parse(sessionStorage.getItem("goods")) || [];
    console.log(goodsData)
    // 🔧 格式化商品数据，统一字段
    const formattedGoods = goodsData.map(item => ({
      ...item,
      productId: item.productId || item.detail?.id || item.detail?.product_id || item.detail?.itemNo || "",
      displayName: item.detail?.name || item.detail?.showNameCn || item.nameCn || item.detail?.product_name || item.detail?.title || item.itemName || '商品',
      // 🔧 修复图片：从 detail.img 或 detail.condimentRoundList 中取
      displayImage: item.detail?.coverUrl || item.detail?.img || item.detail?.imageUrl || item.imageUrl || item.itemImage || '',
      displaySpec: item.specifications || item.specKey || item.detail?.name || '',
      displayPrice: item.fullPrice || item.price || item.detail?.price || item.detail?.salePrice || 0,
      displayCount: item.count || 1
    }));

    this.shopcarlist = formattedGoods;
    this.verify = formattedGoods;
    this.goods = formattedGoods.slice(0, 2);

    // 计算总价
    this.sumprice = 0;
    formattedGoods.forEach(item => {
      this.sumprice += item.displayPrice * item.displayCount;
    });

    // 外卖模式加上配送费
    if (this.flagA) {
      this.sumprice += Number(this.deliveryPrice);
    }

    this.storecode = this.shopcarlist[0]?.storeCode || this.shopcarlist[0]?.storeId
  },
  methods: {
    // 展开
    unfold() {
      this.isUnfold = !this.isUnfold
      if (this.isUnfold) {
        this.goods = this.verify
      } else {
        this.goods = this.verify.slice(0, 2)
      }
    },
    changePackFlag(item) {
      this.packFlag = item.packFlag
    },
    input(e) {
      this.isShow = e
    },
    // 密码输入
    onInput(key) {
      this.pass = key
      if (this.pass.length == 6) {
        this.isShow = false
        this.flkpay(this.pass)
        this.pass = ""
      }
    },
    // 福利卡支付
    flkpay(pass) {
      let data = {
        ka_ids: this.ka_ids,
        pass,
        storeCode: this.storecode,
        type: this.type,
        packFlag: this.packFlag,
        orderType: this.packFlag,
        phone: this.phone,
        goods: this.verify,
        receiverLng: this.flagA ? this.address_Item.lon : '',
        receiverLat: this.flagA ? this.address_Item.lat : '',
        address_id: this.flagA ? this.address_id : ''
      }
      flkpay(data).then(res => {
        // console.log(res);
        if (res.code == 200 && res.data) {
          this.getcard()
          if (res.code == 200 && res.data) {
            setTimeout(() => {
              this.$router.replace({ path: "/order", query: { tabIndex: 1 } })
            }, 1000)
          }
        } else {
          this.$toast(res.msg)
        }
      })
    },
    // 选择支付方式
    getResult(result, checked) {
      this.result = result
      this.checked = checked
    },
    // 微信支付
    wxpay(ka_ids = []) {
      let data = {
        ka_ids,
        openid: this.openid,
        storeCode: this.storecode,
        type: this.type,
        packFlag: this.packFlag,
        orderType: this.packFlag,
        phone: this.phone,
        goods: this.verify,
        receiverLng: this.flagA ? this.address_Item.lon : '',
        receiverLat: this.flagA ? this.address_Item.lat : '',
        address_id: this.flagA ? this.address_id : ''
      }
      wxpay(data).then(res => {
        if (res.code == 200) {
          this.onBridgeReady(res.data.jsApiParameters, res.data.order_no)
        } else {
          this.$toast(res.msg)
        }
      })
    },
    unique(arr) {
      const res = new Map();
      return arr.filter((arr) => !res.has(arr.productId) && res.set(arr.productId, 1)
      );
    },
    // 去结算
    // 去结算
    toPay() {
      if (this.num1 == 3 || this.num1 == 1 && this.flagA || this.num1 == 2 && this.flagA) {
        this.$router.push({
          path: "/checkstand",
          query: {
            flag: this.flagA,
            num1: this.num1,
            num2: this.num2,
            type: this.type,
            shopName: this.$route.query.shopName,
            deliveryPrice: this.deliveryPrice || 0
          }
        })
        return
      }
      this.$toast.loading({
        message: '加载中...',
        forbidClick: true,
        duration: 100000
      });

      // ✅ 从多个来源获取 shopId
      const shopId = this.goods[0]?.storeid
        || this.shopcarlist[0]?.storeid
        || this.shopcarlist[0]?.storeCode
        || this.$route.query.storeid
        || '';

      // ✅ 验证必要字段
      if (!shopId) {
        this.$toast.clear();
        this.$toast('店铺信息缺失');
        return;
      }

      let data = {
        "shopId": shopId,
        type: this.type,
        "eatType": this.packFlag,
        "products": [],
        "phone": this.phone,
      }

      // ✅ 使用 verify（完整商品列表）
      const verify = this.verify.length > 0 ? this.verify : this.shopcarlist;

      verify.forEach(item => {
        const isMeal = item.detail?.isMultiSpec == 1;

        data.products.push({
          "productId": item.productId || item.detail?.product_id || item.detail?.itemNo || item.code || "",
          "linkId": isMeal ? (item.detail?.linkId || "") : (item.linkId || item.code || ""),
          "quantity": item.count || item.quantity || 1,
          "nameCn": item.displayName || item.nameCn || item.detail?.product_name || "",
          "imageUrl": item.displayImage || item.imageUrl || item.detail?.product_img || "",
          "sellPrice": isMeal ? (item.fullPrice || item.detail?.salePrice || 0) : (item.priceHead || item.detail?.salePrice || 0),
          "oPrice": item.fullPrice || item.price || 0,
          "config": item.specifications || item.listname || "",
          "selected": isMeal && item.detail?.selected?.length > 0
            ? [{
              round: 0,
              products: item.detail.selected.map(s => ({
                linkId: s.linkId || "",
                productId: s.productId || s.linkId || "",
                quantity: 1
              }))
            }]
            : [{
              round: 0,
              products: []
            }]
        });
        const currentProduct = data.products[data.products.length - 1];
        // ✅ 处理麦当劳套餐的 selected（原有逻辑）
        if (item.detail) {
          data.products.forEach(item5 => {
            let list = item.detail.details
              ? (item.detail.details.optional || item.detail.details.spu_specs || item.detail.details.specifications)
              : (item.detail.specItems || []);

            if (list && list.length > 0) {
              list.forEach((item2, index2) => {
                if (item2.sku_infos) {
                  if ((item.productId || item.detail.product_id || item.detail.itemNo) == item5.productId) {
                    item2.sku_infos.forEach(item3 => {
                      if (item3.checked) {
                        item5.selected.forEach(item6 => {
                          item6.round = 0;
                          item6.products.push({
                            "linkId": item2.id,
                            "productId": item3.id,
                            "quantity": 1
                          });
                        });
                      }
                    });
                  }
                } else {
                  // 处理其他品牌（num1 == 5, 6, 7）的逻辑
                  if (this.num1 == 5 && item.detail.product_id == item5.productId) {
                    item2.values.forEach((item3, index3) => {
                      if (item3.checked == 1) {
                        item.detail.details.sku_infos.forEach((item7) => {
                          item7.specs.forEach((item8, index8) => {
                            if (item3.code == item8.spec_code && item2.code == item8.code) {
                              item8.checked = 1;
                            }
                          });
                          if (item7.specs.filter(item => item.checked == 1).length == item7.specs.length) {
                            item5.selected.forEach(item6 => {
                              item6.round = 0;
                              item6.products = [];
                              item6.products.push({
                                "linkId": "",
                                "productId": item7.code,
                                "quantity": 1
                              });
                              item6.products = this.unique(item6.products);
                            });
                          }
                        });
                      }
                    });
                  } else if (this.num1 == 6 && item.detail.product_id == item5.productId) {
                    const configArr = [];
                    item2.ingredients.forEach(item3 => {
                      if (item3.checked) configArr.push(item3.name);
                    });

                    const matched = (item.detail.details.sku_infos || []).find(sku => {
                      const values = sku.values.map(v => v.spec_name);
                      return values.length === configArr.length &&
                        values.every((v, i) => v === configArr[i]);
                    });

                    if (matched) {
                      currentProduct.selected = [{          // ← 只改这一行：item5 → currentProduct
                        round: 0,
                        products: [{
                          linkId: "",
                          productId: matched.code,
                          quantity: item.count || item.quantity || 1
                        }]
                      }];
                    } else if (item.skuCode) {
                      currentProduct.selected = [{          // ← 兜底：item5 → currentProduct
                        round: 0,
                        products: [{
                          linkId: "",
                          productId: item.skuCode,
                          quantity: item.count || item.quantity || 1
                        }]
                      }];
                    }
                  }
                  else if (this.num1 == 7 && item.detail.itemNo == item5.productId) {
                    item2.specValueList.forEach((item3, index3) => {
                      if (item3.recommendFlag == 1) {
                        item.detail.skuCombinList.forEach((item7) => {
                          item7.skusSpecs.forEach((item8, index8) => {
                            if (item3.name == item8.specItemValueName) {
                              item8.recommendFlag = 1;
                            }
                          });
                          if (item7.skusSpecs.filter(item => item.recommendFlag == 1).length == item7.skusSpecs.length) {
                            item5.selected.forEach(item6 => {
                              item6.round = 0;
                              item6.products.push({
                                "linkId": "",
                                "productId": item7.skuNo,
                                "quantity": 1
                              });
                            });
                            item5.linkId = item7.skuNo;
                          }
                        });
                      }
                    });
                  }
                }
              });
            }
          });
        } else {
          // 没有 detail 的商品，清空 selected
          data.products.forEach(item5 => {
            if ((item.productId || item.detail?.product_id || item.detail?.itemNo) == item5.productId) {
              item5.selected = [];
            }
          });
        }
      });

      data.products = JSON.stringify(data.products);

      create_order(data).then(res => {
        this.$toast.clear();
        if (res.code == 200) {
          this.$router.replace({
            path: "/checkstand",
            query: {
              flag: this.flagA,
              num1: this.num1,
              num2: this.num2,
              type: this.type,
              shopName: this.$route.query.shopName,
              deliveryPrice: this.deliveryPrice || 0,
              orderid: res.data.orderid
            }
          });
        } else {
          this.$toast(res.msg);
        }
      });
    },
    uniqueProducts(products) {
      const map = new Map()
      return products.filter(item => {
        if (!map.has(item.productId)) {
          map.set(item.productId, true)
          return true
        }
        return false
      })
    },
    // 判断是否在微信中打开
    isWeiXin() {
      var ua = window.navigator.userAgent.toLowerCase();
      if (ua.match(/MicroMessenger/i) == "micromessenger") {
        return true;
      } else {
        return false;
      }
    },
    // 计算福利卡是否够支付
    isPay_date() {
      let data = {
        'fulika': this.result.join(","),
        'storeCode': this.storecode,
        'goods': this.verify,
        'type': this.type,
        'receiverLng': this.flagA ? this.address_Item.lon : '',
        'receiverLat': this.flagA ? this.address_Item.lat : '',
        'packFlag': this.packFlag,
        'orderType': this.packFlag,
        'address_id': this.flagA ? this.address_id : ''
      }
      getcardPay(data).then(res => {
        if (res.code == 200) {
          this.wxprice = res.data.wxprice
          this.dkprice = res.data.dkprice
          this.ka_ids = res.data.ka_ids
          // 福利卡支付价格
          if (this.wxprice != 0) {
            // 微信支付
            if (!this.isWeiXin()) {
              this.$toast("请使用微信打开进行支付")
              this.isLoading = false
              return;
            }
            this.wxpay(this.ka_ids)

          } else {
            // console.log("卡够了");
            // 去福利卡支付
            if (this.dkprice != 0) {
              // console.log("卡支付")
              this.isShow = true
            }
          }
        } else {
          this.$toast(res.msg)
        }
      })
    },
    // 协议
    getsinglelist() {
      getsingle({
        type: this.type,
        flag: '2'
      }).then(res => {
        // console.log(res);
        this.goumaixuzhi = res.data.content
      })
    },
    // 福利卡列表
    getcard() {
      this.result = []
      getcardList().then(res => {
        this.loadingflag = false
        if (res.code == 200) {
          this.cardList = res.data.card_list
          if (this.cardList.length !== 0) {
            this.result.push(this.cardList[0].id)
          }
          // console.log(res.data.card_list);
        }
      })
      if (!this.flagA) {
        getPhone().then(res => {
          // console.log(res, "电话");
          if (res.code == 200) {
            this.phone = res.data.all_phone
          }
        })
      } else {
        this.phone = this.address_Item.phone
      }
    },
    // 调取微信支付
    onBridgeReady(params, order_no) {
      var that = this
      // "jsApiParameters": { //支付信息
      //   "appId": "wx05cc5223511e93c3",
      //       "timeStamp": "1710496158",
      //       "nonceStr": "qx0rpl2z6aqb492cvejftx5p4dowya4u",
      //       "package": "prepay_id=wx15174918865168a10f39f811aca3ea0000",
      //       "signType": "MD5",
      //       "paySign": "F0A17328ADD15AA9171CAEB082261A47"
      // }
      WeixinJSBridge.invoke(
        'getBrandWCPayRequest', {
        "appId": params.appId,  //公众号名称，由商户传入
        "timeStamp": params.timeStamp, //支付签名时间戳，注意微信jssdk中的所有使用timestamp字段均为小写。但最新版的支付后台生成签名使用的timeStamp字段名需大写其中的S字符
        "nonceStr": params.nonceStr,  //支付签名随机串，不长于 32 位
        "package": params.package,//统一支付接口返回的prepay_id参数值，提交格式如：prepay_id=\*\*\*）
        "signType": params.signType,  //签名方式，默认为'SHA1'，使用新版支付需传入'MD5'
        "paySign": params.paySign, //支付签名
      },
        function (res) {
          if (res.err_msg === "get_brand_wcpay_request:ok") {
            this.getcard()
            setTimeout(() => {
              that.$toast('支付成功');
              that.$router.replace({ path: "/order", query: { tabIndex: 1 } })
              // window.location.href = this.$store.state.Shopbase + "/orderInfo?tabIndex=0&token=" + localStorage.getItem("token")
            }, 1000)
          } else if (res.err_msg === "get_brand_wcpay_request:fail") {
            that.$toast('支付失败');
          }
          if (res.err_msg) {
            pay_success({
              order_no
            }).then(res => {
              that.$toast(res.msg)
              if (res.code == 200) {

              }
            })
          }
        });
    },
  }
  ,
  mounted() {

    document.body.scrollTop = 0

    // firefox

    document.documentElement.scrollTop = 0

    // safari

    window.pageYOffset = 0
  }
};
</script>

