  }
  
  console.log('this.verify', this.verify)
  
  // 遍历商品，构建goods数组
  this.verify.forEach(item => {
    // 基础商品信息
    let goodsItem = {
      goodsId: item.productId || item.detail.product_id || item.detail.id || item.id, // 商品ID
      skuId: item.skuId || item.detail.skus?.[0]?.id || '', // SKU ID
      quantity: item.count || item.quantity, // 数量
      specOptions: [] // 规格选项集合
    }
    
    // 处理商品规格选项
    if (item.detail && item.detail.specs && Array.isArray(item.detail.specs)) {
      item.detail.specs.forEach(spec => {
        if (spec.options && Array.isArray(spec.options)) {
          spec.options.forEach(option => {
            // 如果这个选项被选中（isDefault为true）
            if (option.isDefault) {
              goodsItem.specOptions.push({
                specId: spec.specId, // 规格Id
                optionId: option.optionId, // 选项Id
                quantity: 1 // 数量，默认为1
              });
            }
          });
        }
      });
    }
    
    // 处理通过selectedData保存的规格选项（如果有）
